#ifndef REGISTER_H
#define REGISTER_H

template <typename T>
class Register {
public:
  T prev;
  T next;
  bool _stall;

  Register();
  Register(T d);

  T read() const;
  T current() const;
  void write(const T &t);
  void tick();
  void stall(bool stall);
  operator T() const;
  void operator=(T next);
};

#endif // REGISTER_H
